a<-commandArgs(trailingOnly=TRUE);d<-read.delim(a[1],stringsAsFactors=FALSE);png(a[2],width=1800,height=1300,res=150);layout(matrix(c(1,2,3,4),nrow=2,byrow=TRUE),heights=c(4,1.8));par(oma=c(0,0,2,0));lim<-range(c(d$dimension_1,d$dimension_2));pad<-diff(lim)*0.12;lim<-c(lim[1]-pad,lim[2]+pad)
for(tp in c('sleep','disorder')){par(mar=c(4,4.5,3,1));x<-d[d$type==tp,];plot(x$dimension_1,x$dimension_2,xlim=lim,ylim=lim,xlab='Dimension 1',ylab='Dimension 2',main=if(tp=='sleep')'Sleep traits' else 'Brain disorders',pch=19,col=if(tp=='sleep')'#177e89' else '#cc6440',cex=1.2);abline(h=0,v=0,col='#bbbbbb',lty=3);text(x$dimension_1,x$dimension_2,labels=seq_len(nrow(x)),pos=3,cex=.8)}
for(tp in c('sleep','disorder')){par(mar=c(0,4,0,1));x<-d[d$type==tp,];plot.new();plot.window(xlim=c(0,2),ylim=c(0,6.5));for(i in seq_len(nrow(x))){col<-floor((i-1)/6);row<-(i-1)%%6;text(col,6-row,paste0(i,'  ',x$trait[i]),adj=0,cex=.8)}}
mtext('Rank-2 embedding of 72 genetic-correlation estimates',outer=TRUE,cex=1.1);dev.off()
